// Original editorial text; location names and mechanics refer to Final Fantasy VII (1997).
const C=[];
function chapter(disc,title,area,summary,steps,loot,boss,note){C.push({id:'c'+(C.length+1),disc,title,area,summary,steps,loot:loot||[],boss,note});}
chapter(1,'The No. 1 reactor','MIDGAR · SECTOR 1','A train, a mercenary, and a ten-minute escape. Your journey begins beneath the plate.',[
['Join AVALANCHE','Check the fallen guards at the station for Potions. Follow Barret through the gate, then speak with Biggs and Jessie to open the reactor doors.'],
['Descend to the core','Take the elevator down and follow the ladders. Pick up the Phoenix Down and Potion along the route. Use the save point before the final descent.'],
['Secure Restore','Pick up the green Restore Materia on the walkway before setting the charge. It will become your early healing magic once the Materia menu is available.'],
['Defeat Guard Scorpion','Use Bolt with Cloud and regular attacks with Barret. When the tail rises, stop attacking and heal until it lowers. The old English battle warning is misleading.'],
['Escape the reactor','You have ten minutes. Retrace your route, free Jessie where her foot is stuck, and speak with your allies at the doors. Equip Barret’s Assault Gun after the battle.'],
['Reach the train','Move through Sector 8 after the explosion. The flower purchase is optional and affects later relationship opportunities. Head south; fight or evade the soldiers until Cloud boards the train.']
],[['Restore','Core walkway','Collect before setting the bomb.','important'],['Assault Gun','Guard Scorpion reward','Equip on Barret after escaping.','weapon']],{name:'Guard Scorpion',hp:'800',element:'Lightning',tactic:'Bolt is your strongest early tool. Keep someone healthy enough to heal. A raised tail means wait: attacking it triggers Tail Laser.',prep:'Cloud: Lightning + Restore. Barret: back row with his ranged weapon. Keep Potions ready.'},'Use separate save slots at major story transitions. The guide tracks your checklists, not the game’s save data.');
chapter(1,'Seventh Heaven','MIDGAR · SECTOR 7','Regroup at the hideout and prepare a three-person party.',[
['Return to the bar','Leave the train station toward Sector 7. Enter Seventh Heaven, speak with Tifa, and use the pinball lift when the meeting begins.'],['Finish the briefing','Follow the conversations, rest, and speak with Barret in the morning. Review the Materia tutorial if this is your first playthrough.'],['Visit the beginner’s hall','Go upstairs in the weapon shop. Pick up All and open the nearby Ether chest. Link All with Restore in a connected pair of slots.'],['Prepare equipment','Buy defensive upgrades if affordable, keep a few Potions and Phoenix Downs, and give each party member a useful job. Too much magic Materia lowers HP.'],['Board the next train','Save before leaving for the station. The next operation includes timed carriage changes.']
],[['All','Beginner’s hall','Pick it up upstairs in the Sector 7 weapon shop.','important']],null,'Dialogue choices throughout Disc 1 can affect the Gold Saucer date. This route does not optimize a particular date or a version-specific trophy.');
chapter(1,'The No. 5 reactor','MIDGAR · SECTORS 4–5','Slip past the security checks and take on a second reactor.',[
['Pass the train checks','Move to the next carriage before each countdown ends. Keep going toward the front until the party jumps from the train.'],['Enter the maintenance route','Follow the rail tunnel toward the laser barrier and use the side ventilation passage. Descend through the maintenance platforms.'],['Plant the charge','Follow the familiar reactor layout down to the core. Return upstairs afterward; this escape has no ten-minute timer.'],['Open the synchronized door','At the three switches, time Cloud’s press with Tifa and Barret. Repeat until the door opens, then save and restore HP.'],['Fight Air Buster','Attack the rear of the machine when it turns away. Use Bolt and Limit Breaks, keeping Cloud and the other two groups healed separately.']
],[],{name:'Air Buster',hp:'1,200',element:'Lightning',tactic:'Rear attacks deal extra damage. Time physical attacks and Limits when the boss faces the other side. Heal before pushing damage.',prep:'Lightning on your main caster, Restore on another character, and Potions for either side.'});
chapter(1,'Flowers in the slums','MIDGAR · SECTOR 5','Meet Aeris and find a way through the broken streets.',[
['Leave the church','Help Aeris through the rafters while the soldiers pursue her. Barrel choices affect affection, but mistakes do not block the story. Follow her over the rooftops.'],['Explore Sector 5','Visit the shops and the house on the right. Read the Turtle’s Paradise flyer upstairs. Leave the sleeping child’s hidden 5 gil alone for a later reward.'],['Check the garden','Before entering Aeris’s house, collect Cover and the Ether outside. Rest after the conversations.'],['Slip out quietly','Walk past Aeris’s door instead of running. Leave the house and return toward Sector 6; Aeris will catch up with you.'],['Cross to Wall Market','Follow the ruined road and pass through the playground. After the carriage scene, go east to Wall Market.']
],[['Cover','Aeris’s garden','Search outside the house.','materia'],['Turtle’s Paradise #1','Sector 5 house','Read the upstairs wall notice.','quest']],null,'The original English localization calls this character Aeris. Some ports and fan translations use Aerith; both refer to the same character.');
chapter(1,'Wall Market','MIDGAR · SECTOR 6','Assemble a disguise and enter Don Corneo’s mansion.',[
['Find Tifa’s trail','Ask at the Honey Bee Inn, then speak to the guard outside Corneo’s mansion. Cloud needs a disguise before the guard will admit him.'],['Arrange the dress','Talk to the girl in the clothing shop, find her father at the bar, and choose a dress style. Return to the clothing shop to collect it.'],['Win a wig','Enter the gym and complete the squat contest. A better result improves the disguise, but winning is not required to continue.'],['Optional: improve the disguise','For the tiara, help the Materia shopkeeper by buying from the inn vending machine. For cologne, use the restaurant coupon at the pharmacy and help the woman in the bar bathroom. Honey Bee Inn items and makeup are optional.'],['Enter the mansion','Change at the dress shop, enter the mansion, and find Tifa in the basement. Follow the selection sequence, regroup, and confront Corneo. The story continues regardless of whom he chooses.']
],[],null,'Disguise quality changes Corneo’s choice, not access to the next story area. Make a separate save if you want to replay the selection.');
chapter(1,'Sewers, trains & the pillar','MIDGAR · SECTOR 7','Fight your way back to the support pillar.',[
['Beat Aps','Heal after the fall. Aps’s sewer attacks can damage both sides; Fire and ordinary attacks work while a dedicated healer keeps the group stable.'],['Exit the sewers','Pick up Steal and follow the ladders and channels toward the Train Graveyard. Check the walkway branches for items.'],['Move the trains','Climb the abandoned cars, enter the locomotive cabs, and drive the movable engines to create a crossing. Climb over the newly aligned cars to exit west.'],['Climb the pillar','Speak to your injured allies if you wish. At the top, Barret joins; open the menu immediately to heal and equip him before the battle.'],['Break Reno’s pyramids','Attack an imprisoned ally to destroy their pyramid. Keep at least one party member free and healthy. Follow the escape sequence after the fight.']
],[['Steal','Sewer passage','Pick up the yellow Materia on your way out.','materia']],{name:'Reno',hp:'1,000',element:'No required element',tactic:'A pyramid is removed by attacking the trapped character. Prioritize freeing allies before all three are captured.',prep:'Restore + All, Potions, and a freshly equipped Barret.'});
chapter(1,'Climb to Shinra','MIDGAR · WALL MARKET','Return to the slums and reach the upper plate.',[
['Return to Aeris’s house','Travel through Sector 6 to Sector 5 and finish the conversations with Elmyra and Barret.'],['Resupply in Wall Market','Buy Batteries from the weapon shop’s left counter. You need them for the climb. Save and stock healing items.'],['Find the wall route','Follow the children in the northern part of Wall Market to the wire. Climb up to the rubble above the slums.'],['Power the machinery','Use Batteries in the machinery sockets to create crossings. At the swinging cable, jump as it swings close to Cloud.'],['Choose your entrance','At Shinra HQ, the stairs avoid most entrance fights. The front entrance offers combat and access to the lobby flyer. Both routes reach floor 59.']
],[],null,'If you take the stairs, make time to visit the lobby for Turtle’s Paradise flyer #2 before you leave the building.');
chapter(1,'Shinra headquarters','MIDGAR · FLOORS 59–70','Navigate the tower, free your friends, and get out of the city.',[
['Obtain the floor keycards','Beat the guards on 59, cross floor 60 behind the statues, and talk to the employee on 61 without revealing your identity to obtain access.'],['Solve the library password','On 62, identify the misplaced book in each library room. Use the number at the beginning of each book title to select a letter; rearrange the four letters into the password. Save first if chasing the best reward.'],['Explore the upper floors','Floor 63 offers a door-opening treasure puzzle. Rest and save on 64. On 65, use the Midgar model pieces to open more chests until you obtain the next keycard.'],['Reach the laboratory','Use the bathroom vent on 66 to observe the meeting. Follow Hojo to 67 and continue to the specimen area. After Sample:H0512, collect Enemy Skill from the chamber floor.'],['Follow the overnight trail','After the cells, follow the trail through the tower. Prepare two teams: Cloud fights Rufus alone, while the elevator party needs healing and ranged attacks.'],['Escape on the highway','Redistribute Materia before the motorcycle sequence. Against Motor Ball, use Lightning and group healing. Leave Midgar to the world map.']
],[['Elemental','Floor 62','Best password reward: solve it on the first attempt.','important'],['Enemy Skill','Floor 68 specimen chamber','Collect after the laboratory boss.','important'],['Turtle’s Paradise #2','Ground-floor lobby','Read the notice; this visit or the late return are your opportunities.','quest']],{name:'Rufus / Motor Ball',hp:'500 / 2,600',element:'Motor Ball: Lightning',tactic:'For Rufus, eliminate Dark Nation’s support first. On the road, keep the whole party healed before Motor Ball’s strong fire attack.',prep:'Give Cloud Restore for his solo battle. Before the highway, re-equip all three active characters.'});
chapter(1,'Kalm & the marsh','EASTERN CONTINENT','Hear Cloud’s story and find a safer way across the swamp.',[
['Reach Kalm','Travel northeast from Midgar to Kalm. Go upstairs in the inn and complete the flashback. Explore the town’s houses and shops afterward.'],['Prepare for travel','Buy useful magic and defensive upgrades. Kalm is a convenient point to start using separate attack and healing casters.'],['Visit the Chocobo Farm','Talk to the Chocobo in the pen for Choco/Mog. Buy Chocobo Lure from Choco Billy and obtain greens. Equip the lure before walking on tracks.'],['Catch a Chocobo','In a battle containing a Chocobo, feed it greens and defeat the other enemies without striking it. Ride across the swamp. Stay mounted until clear of the Midgar Zolom.'],['Cross Mythril Mine','Enter the cave beyond the swamp, collect Long Range on the climbable ledge, and follow the tunnels through the Turks’ scene to the exit.']
],[['Choco/Mog','Farm pen','Interact with the Chocobo and watch its dance.','summon'],['Long Range','Mythril Mine','Climb the vine to the upper ledge.','materia']],null,'The Midgar Zolom is much stronger than your party here. Catching a Chocobo is the intended early crossing method; learning Beta can wait.');
chapter(1,'Junon & the parade','EASTERN CONTINENT · JUNON','Save a child, join a parade, and stow away.',[
['Explore the coast','After the mine, Fort Condor is an optional stop. Forest encounters can introduce Yuffie; her recruitment route is in Side quests. Continue north to Junon.'],['Defeat Bottomswell','Enter the beach below Junon. Use ranged weapons or magic. Remove a trapped ally’s water bubble with magic directed at the bubble.'],['Help Priscilla','Complete the breathing minigame and rest. Visit her again for Shiva, then use the dolphin to reach the upper structures.'],['Perform in the parade','Learn the march and rifle commands from the soldiers. Parade ratings affect rewards but do not prevent you from boarding the ship.'],['Explore before departure','Check the barracks and shops; collect the Enemy Skill Materia in the beginner training room. Finish the send-off performance, then board the cargo ship.']
],[['Shiva','Priscilla','Speak with her after she recovers.','summon'],['Enemy Skill','Upper Junon training room','Search the beginner’s hall.','important']],{name:'Bottomswell',hp:'2,500',element:'Wind',tactic:'Melee characters need magic or Long Range to reach this flying boss. Cast magic on a water bubble to free its captive.',prep:'Long Range, healing, and several offensive spells.'});
chapter(1,'Across the sea','CARGO SHIP → COSTA DEL SOL','Reach the western continent and climb toward North Corel.',[
['Find the disguised party','Talk to your allies aboard the ship. Find Barret at the bow after the initial conversations; return when the alarm sounds.'],['Enter the hold','Reorganize the party and descend to the cargo hold. Heal before approaching the disturbance.'],['Collect the summon','Defeat Jenova∙BIRTH, then pick up the red Ifrit Materia before leaving the room.'],['Explore Costa del Sol','Rest and check the shops. Cross the western exit to reach the world map; buying the villa is optional and expensive.'],['Head for Mount Corel','Follow the western continent north and inland. Enter the mountain trail and pass the reactor on the way toward the railway.']
],[['Ifrit','Cargo ship boss room','Collect before leaving the ship.','missable']],{name:'Jenova∙BIRTH',hp:'4,000',element:'No required element',tactic:'Keep healing available for multi-target damage and repeated attacks. Limits and your strongest normal spells do steady work.',prep:'Restore + All and sufficient MP for a longer fight.'});
chapter(1,'Corel & the Gold Saucer','WESTERN CONTINENT','A mountain railway leads to the world’s loudest amusement park.',[
['Traverse the tracks','Follow the rail bridges above Corel. If a section breaks and you fall, steer left or right to grab the bonus treasure on the way down.'],['Lower the bridge','Use the switch in the small hut to clear the party’s path. Continue across the railway to North Corel.'],['Ride the ropeway','Explore North Corel, save, and take the cable car to Gold Saucer. Entrance costs gil; many park activities use GP instead.'],['Meet Cait Sith','Explore Wonder Square and follow the introduction. Continue the story in Battle Square, which sends the party to Corel Prison.'],['Find Dyne','Gather information in the prison, recruit Barret for the confrontation, and head through the desert screens toward Dyne’s area. Keep Barret healed for the solo fight.'],['Win your freedom','After Dyne, return to Mr. Coates. In the jockey room, collect Ramuh before racing. Win the Chocobo race to obtain the buggy and leave.']
],[['Ramuh','Chocobo jockey room','Collect before starting the prison escape race.','missable']],{name:'Dyne',hp:'1,200',element:'No required element',tactic:'Barret fights alone. Heal early and use his Limit whenever possible. Do not enter with a low-HP magic-heavy setup.',prep:'Put Restore on Barret and equip his best available armor.'});
chapter(1,'Gongaga & Cosmo Canyon','WESTERN CONTINENT','Follow the southern road before entering Red XIII’s hometown.',[
['Optional: explore Gongaga','Drive the buggy toward the ruined reactor in the forest. Fight Reno and Rude on the approach if taking this detour.'],['Search the reactor','After the Shinra scene, inspect the ruined reactor for Titan. Explore the village, then return to the world map.'],['Reach Cosmo Canyon','Drive west across the shallow river crossing and approach Cosmo Canyon. Enter the town after the buggy trouble.'],['Meet Bugenhagen','Follow Red XIII up to the observatory and watch the planetarium demonstration. Speak to your companions and join the campfire sequence.'],['Enter the Cave of the Gi','Return to Bugenhagen with a selected party. Examine the small cave switches to open the route, take care on slippery oil, and follow the tunnels.'],['Face Gi Nattak','Heal before the final chamber. Healing magic or an X-Potion damages the undead boss; a Phoenix Down can work but is not guaranteed. Finish the story and leave town.']
],[['Titan','Gongaga ruined reactor','Inspect the debris after the scene.','summon'],['Added Effect','Cave of the Gi','Explore the lower connecting path.','materia']],{name:'Gi Nattak',hp:'5,500',element:'Healing harms undead',tactic:'An X-Potion is an effective shortcut against the main boss. Otherwise keep the party healed and focus damage on Gi Nattak.',prep:'Healing items; avoid depending on fire damage.'});
chapter(1,'Nibelheim & Mount Nibel','WESTERN CONTINENT','Investigate the mansion and climb the mountain beyond it.',[
['Investigate the town','Explore the rebuilt houses, then enter Shinra Mansion. Loot the side rooms before going through the secret stairway in the upstairs room.'],['Visit the basement library','Follow the spiral stairway and cave to the library. Complete the meeting and collect Destruct before leaving.'],['Optional: recruit Vincent','Open the mansion safe and defeat Lost Number to obtain the basement key. The exact dial sequence and recruitment dialogue are in Side quests.'],['Cross Mount Nibel','Follow the bridges through the mountain. In the pipe room, lower the ladder before experimenting with pipes so you can return and claim the side treasures.'],['Defeat Materia Keeper','Save near the lower exit. Equip Enemy Skill on someone who can survive Trine. After the battle, collect Counter Attack and leave toward Rocket Town.']
],[['Destruct','Mansion basement library','Collect after the encounter.','materia'],['Counter Attack','Mount Nibel boss area','Appears after Materia Keeper.','materia']],{name:'Materia Keeper',hp:'8,400',element:'Avoid Fire',tactic:'It absorbs Fire. Keep HP high enough to survive Trine, and equip Enemy Skill to learn it when struck and surviving. Use non-fire attacks.',prep:'Restore + All, Enemy Skill, and strong physical weapons.'});
chapter(1,'Rocket Town','WESTERN CONTINENT','Meet Cid and acquire an unusual way to cross the ocean.',[
['Explore the town','Talk to the old man looking at the rocket repeatedly and look at it with him for Yoshiyuki. Buy upgrades and save.'],['Visit Cid’s house','Speak with Shera, then climb the rocket to meet Cid. Return to the house for the Shinra visit.'],['Prepare for Palmer','Go to the backyard airstrip. Heal and equip before confronting Palmer near the Tiny Bronco.'],['Escape with Cid','Defeat Palmer and follow the takeoff sequence. The damaged Tiny Bronco becomes a shallow-water vehicle.'],['Choose your next route','You can travel to Wutai for an optional quest, or pursue the Keystone by returning toward Gold Saucer via North Corel.']
],[['Yoshiyuki','Rocket Town old man','Accept his invitation to look at the rocket.','important']],{name:'Palmer',hp:'6,000',element:'No required element',tactic:'Mako Gun uses elemental spells. Heal consistently and use Limits to shorten the encounter.',prep:'Good armor, Restore, and non-elemental physical damage.'});
chapter(1,'The Keystone','GOLD SAUCER · SECOND VISIT','A return to the park opens the path to the temple.',[
['Locate the Keystone','The weapon seller’s house near Gongaga explains that Dio now owns it. Travel back through North Corel to Gold Saucer.'],['Talk to Dio','Inspect the Keystone in the Battle Square showroom. Accept Dio’s arena challenge; you do not need a perfect run to advance the story.'],['Stay at the Ghost Hotel','When the ropeway is unavailable, return toward the entrance and follow the hotel events. Your date partner depends on earlier dialogue choices.'],['Follow Cait Sith','After the date, chase him through the park. Complete the confrontation and regroup at the hotel.'],['Sail to the temple','Take the Tiny Bronco to the temple island south of the eastern continent. Prepare Aeris, who is required for the dungeon.']
],[],null,'Before the temple, make a separate save and finish any Aeris equipment or Limit goals you personally want to pursue.');
chapter(1,'Temple of the Ancients','SOUTHERN ISLAND','Navigate the maze and collect its unique rewards before proceeding.',[
['Enter the temple maze','Follow the Cetra spirit through the stepped, isometric rooms. Explore the side paths, particularly for Luck Plus, before moving to the rolling passage.'],['Pass the rolling stones','Move into each hollow as the curved stones roll past. Reach the pool, watch its scene, and use the spirit to heal or save.'],['Explore the clock rooms','Set the hands to create bridges to the side rooms. Collect Princess Guard from room IV and Ribbon from room V. Falling from a hand leads to a separate battle and treasure room.'],['Catch the door keeper','In room VI, chase the spirit through the connected doorways and intercept its exit. Open the inner door and prepare for Red Dragon.'],['Take Bahamut','After Red Dragon, pick up Bahamut in the room. Inspect the model and follow the scenes. Return toward the clock’s XII route.'],['Defeat Demons Gate','Heal and save at the spirit before committing. Finish the battle, then follow the temple’s final sequence. This dungeon will not remain available.']
],[['Princess Guard','Clock room IV','Aeris’s unique weapon; collect before completing the temple.','missable'],['Ribbon','Clock room V','Protection from many status effects.','important'],['Bahamut','Red Dragon chamber','Pick up the red Materia after the fight.','missable'],['Morph','Rolling-stone passage','Check the passage treasure.','important'],['Luck Plus','Temple maze','Explore the side paths.','important']],{name:'Demons Gate',hp:'10,000',element:'High magic defense',tactic:'Strong physical attacks, Limits and Bahamut are useful. Barrier helps against physical pressure. Keep the healer ready for Demon Rush and use Soft if petrification threatens.',prep:'Restore + All, Time if available, Barrier, Bahamut, and healthy HP totals.'});
chapter(1,'The sleeping forest','NORTHERN CONTINENT','Dig for a key to the forest and follow the trail north.',[
['Reach Bone Village','Travel north with the Tiny Bronco and land near Bone Village. Speak to the excavation foreman.'],['Excavate the Lunar Harp','Hire diggers and trigger the search. Their facing directions point toward the target; place the excavation marker near their intersection on the upper tier. Sleep to receive the result and repeat if needed.'],['Wake the forest','With the Lunar Harp, enter the Sleeping Forest. Watch for the moving red Kjata Materia in the trees and intercept it.'],['Explore the capital','Follow the forest through the valley into the Forgotten Capital. Explore the side houses and paths before resting in the house with beds.'],['Prepare for the altar','Collect Enemy Skill behind the beds, then follow the opened central route down to the altar. Save beforehand.'],['Complete Disc 1','Finish the altar scene and the Jenova∙LIFE battle. Continue northeast out of the capital after the events.']
],[['Kjata','Sleeping Forest','Catch the moving red Materia among the trees.','summon'],['Enemy Skill','Forgotten Capital','Behind the beds in the resting house.','important']],{name:'Jenova∙LIFE',hp:'10,000',element:'Water attacks',tactic:'Equip the Water Ring from the capital to absorb its water damage on one character. Use that character as your safety net for reviving and healing.',prep:'Water Ring, reliable healing, and non-water damage.'});
chapter(2,'Icicle Inn & the glacier','NORTHERN CONTINENT','Follow the mountain trail and cross the frozen wilderness.',[
['Cross the northern trail','Leave the capital to the northeast and follow the spiral shell and mountain paths. Climb the cliff route toward Icicle Inn.'],['Explore Icicle Inn','Buy upgrades, collect the glacier map from the house, and inspect Gast’s recordings if desired. Follow the Elena scene and obtain the snowboard from the child.'],['Snowboard down','Take the slope out of town. Fork choices change your landing point in the Great Glacier, but the routes reconnect.'],['Explore the glacier','Use the map to identify landmarks. Touch the hot spring water, then find the woman in the isolated cave and defeat Snow to receive Alexander.'],['Reach the northern hut','In the snowfield, place markers to preserve your heading during whiteouts. Continue north to Holzoff’s cabin. Collapsing from cold sends you to the cabin rather than ending the game.'],['Rest before climbing','Talk to Holzoff, rest and save. Equip protection against cold and keep status cures for the coming dungeon.']
],[['Alexander','Great Glacier cave','Touch the hot spring first, then speak to Snow.','summon'],['Added Cut','Great Glacier','Explore the connecting snow paths.','materia']],null,'Glacier navigation is easiest with the in-game map. This companion’s Journey view is a chapter route, not a replacement for the field map.');
chapter(2,'Gaea’s Cliff','NORTHERN CONTINENT','Keep warm outside and solve the icy cave passages.',[
['Climb in short stages','At the ledges, raise your body temperature before continuing upward. Do not let it fall too low.'],['Search the first cave','Look for the hidden passage through the wall to a Ribbon chest. Push the large boulder to open the lower route.'],['Clear the icicles','In the upper cave, fight the hanging icicles to drop them and build a path below. Explore the branching ledges for chests.'],['Use the healing spring','Save and restore HP before the final corridor. Keep Enemy Skill equipped if you want to learn useful abilities from enemies along the route.'],['Defeat Schizo','The two heads have different elemental properties. Use non-elemental damage if unsure, and keep the party healthy before killing each head because it retaliates.']
],[['Ribbon','First ice cave','Hidden wall passage; search before climbing onward.','missable'],['Javelin','First cliff cave, upper path','Open the chest on the right side of the upper path.','missable']],{name:'Schizo',hp:'18,000 per head',element:'Fire / Ice heads',tactic:'Avoid healing a head with its own element. Protect against fire, ice and lightning when possible. Each defeated head releases a final attack.',prep:'Non-elemental summons or physical damage, group healing, and elemental defense.'});
chapter(2,'Whirlwind Maze','THE NORTHERN CRATER','A one-way passage with several important pickups.',[
['Descend into the crater','Follow the exposed path down. Tifa joins for this sequence; check her equipment and healing access.'],['Collect Neo Bahamut','Search near the early save point. Pick up the red summon before crossing farther into the maze.'],['Cross the wind barriers','Watch each barrier’s rhythm and cross when the gust fades. A failed crossing causes a battle and returns you to the approach.'],['Defeat Jenova∙DEATH','Use fire protection if available and keep healing active. Continue the party conversations after the fight.'],['Search before proceeding','Collect MP Turbo and Poison Ring along the route. Make a separate save before moving into the final story sequence.'],['Complete the crater events','Follow the guided scenes. The story moves to Junon and a new phase of the journey.']
],[['Neo Bahamut','Near the maze save point','Collect on this visit.','missable'],['MP Turbo','Whirlwind Maze path','Pick up before the final scenes.','missable'],['Poison Ring','Whirlwind Maze chest','Search before leaving the area.','missable']],{name:'Jenova∙DEATH',hp:'25,000',element:'Uses Fire',tactic:'Fire protection reduces much of the threat. Strong physical damage and non-fire summons work well while a healer maintains the party.',prep:'Fire-resistant armor or Elemental + Fire in linked armor slots.'});
chapter(2,'Escape from Junon','JUNON → HIGHWIND','Regroup aboard your new airship.',[
['Follow the escape','During the Junon crisis, control shifts between party members. Follow Cait Sith and Barret through the city toward the airfield.'],['Free Tifa','In the gas chamber, use the on-screen body-part combinations to pick up the key, unlock the restraints, and turn off the gas. Key labels vary by platform.'],['Reach the cannon','Climb through the opening and follow the exterior route onto the cannon. Complete the confrontation with Scarlet.'],['Board the Highwind','Follow the rescue sequence. Speak with the crew and your companions to unlock the airship controls.'],['Find Mideel','Fly to the southeastern islands and enter Mideel. Visit the clinic and complete the reunion; Cid becomes the active leader for the next missions.']
],[],null,'The Highwind can land on open grass. Mountains, forests and desert usually prevent landing. Use its interior operations room to reorganize the party.');
chapter(2,'The Corel train','NORTH COREL · HUGE MATERIA','A timed chase with a permanent outcome. Save before starting.',[
['Save outside the reactor','Fly to North Corel and approach the reactor from the mountain railway. Restore the party before the pursuit begins.'],['Catch the departing train','Use the alternating lever inputs shown by the game to accelerate your engine. The overall mission has a ten-minute limit.'],['Fight through the cars','Move forward from car to car, defeating each guard group. High-damage attacks and Limits conserve time; menus and animations can consume the timer.'],['Stop the train','At the front controls, follow the displayed lever instructions. Keep operating them as directed until the braking sequence resolves.'],['Claim the rewards','A successful stop awards Huge Materia and Ultima from the child. Speak with the woman in town for Barret’s Catastrophe manual. If you fail, reload the separate save if preserving all Huge Materia is your goal.']
],[['Huge Materia · Corel','Stop the train','Mission outcome cannot be replayed in the same save.','missable'],['Ultima','North Corel child','Free for a successful stop; other outcomes differ.','important'],['Catastrophe','North Corel house','Talk to the woman after the mission.','weapon']],null,'Corel and Fort Condor can be completed in either order. This route uses Corel first.');
chapter(2,'The last defense','FORT CONDOR · HUGE MATERIA','Protect the reactor and check both reward locations.',[
['Return to Fort Condor','Land near the fort on the eastern continent. Climb to the lookout and speak to the commander to begin the mandatory defense.'],['Win the defense','Use your units to intercept the advancing enemies. If an enemy reaches the hut, defeat CMD. Grand Horn in a normal battle to save the fort.'],['Visit the summit','After victory and the hatching scene, go outside at the top and collect Phoenix.'],['Talk to the old man','Return downstairs and speak to the old man at the table to receive the Huge Materia. Phoenix and the Huge Materia are separate pickups.'],['Return to Mideel','After finishing both missions, visit the clinic in Mideel to advance the story.']
],[['Phoenix','Fort Condor summit','Collect after the final defense.','important'],['Huge Materia · Condor','Old man downstairs','Speak to him after victory.','missable']],{name:'CMD. Grand Horn',hp:'8,000',element:'No required element',tactic:'If the strategy defense is breached, this battle is your fallback. Use your normal best damage and heal; losing the battle forfeits the fort.',prep:'Save before starting, and equip the party even if planning to win the minigame.'});
chapter(2,'Back to Mideel','SOUTHEASTERN ISLANDS','A short battle leads to an extended story sequence.',[
['Prepare before the clinic','Save outside Mideel. Check that Cid’s party has healing and defensive gear before visiting Tifa.'],['Confront Ultimate Weapon','Survive and deal damage until it withdraws. It is not necessary to defeat it permanently during this encounter.'],['Follow the Lifestream sequence','Explore the memories in each path. Speak to the different versions of Cloud and revisit the central area as scenes unlock.'],['Reunite on the Highwind','Complete the story scenes and speak to the party aboard the airship. Cloud returns as leader.'],['Set course for Junon','Rebuild your preferred team and head to Junon’s underwater reactor for the next Huge Materia mission.']
],[],{name:'Ultimate Weapon · Mideel',hp:'Scripted withdrawal',element:'Non-elemental damage',tactic:'Maintain HP and attack until it leaves. You can attempt to steal Curse Ring during this encounter if collecting rare equipment.',prep:'Strong defenses, party healing, and Steal if pursuing the ring.'});
chapter(2,'The underwater reactor','JUNON · HUGE MATERIA','Push through the reactor and secure a submarine.',[
['Enter upper Junon','Use the elevator from the lower town and follow the city toward the marching soldiers. Enter the interior route and descend toward the underwater facility.'],['Cross the underwater tunnel','If pursuing Underwater Materia, Morph a Ghost Ship here into the Guide Book. The Side quests section explains the exchange.'],['Defeat Carry Armor','Prepare Lightning, strong healing and physical defense before the dock. Destroy its arms to prevent grabs from disabling your whole party.'],['Loot the dock first','Before boarding a submarine, open the dock chests for Battle Trumpet, Scimitar and Leviathan Scales. You cannot freely redo this visit.'],['Win the submarine battle','Read the controls, then pursue and sink the red submarine. It starts ahead of you; aim and fire torpedoes before it escapes. Save before this mission if preserving all Huge Materia.'],['Retrieve the cargo','With your submarine, dive near the southern island chain and inspect the red submarine wreck to recover its Huge Materia. Then head for Rocket Town.']
],[['Leviathan Scales','Submarine dock chest','Needed for Wutai’s fire cave.','missable'],['Scimitar','Submarine dock chest','Cid’s triple-growth weapon.','missable'],['Battle Trumpet','Submarine dock chest','Collect before boarding.','missable'],['Huge Materia · Submarine','Red submarine wreck','Dive and inspect after winning the minigame.','missable']],{name:'Carry Armor',hp:'24,000 body',element:'Lightning',tactic:'The arms can capture party members. Destroy them with Lightning and powerful multi-target attacks, then focus the body. Keep enough HP to survive Lapis Laser.',prep:'Bolt3 or strong Lightning damage, Restore + All, and Barrier or Big Guard if learned.'});
chapter(2,'Into space','ROCKET TOWN · HUGE MATERIA','Return to Cid’s rocket and solve its security lock.',[
['Return with Cid','Fly to Rocket Town. Include Cid and climb toward the rocket, fighting through the guards.'],['Fight Rude','Defeat the soldiers and Rude before boarding. You can attempt to steal his rare armor if collecting enemy equipment.'],['Reach the Materia room','After launch, climb to the upper compartment. Examine the security panel before leaving the rocket.'],['Enter the code','Original PlayStation sequence: Circle, Square, Cross, Cross. By command function: Confirm, Switch, Cancel, Cancel. Match your port’s displayed bindings rather than the physical button positions.'],['Escape the rocket','After collecting the Huge Materia, return downstairs, follow Shera, and reach the escape pod.'],['Visit Cosmo Canyon','Talk to Bugenhagen about the Huge Materia and the next destination. Store the recovered Materia in the observatory.']
],[['Huge Materia · Rocket','Rocket security panel','Solve the lock before escaping.','missable']],null,'If you secured all four Huge Materia and have Bahamut and Neo Bahamut, inspect the blue Huge Materia at the observatory for Bahamut ZERO.');
chapter(2,'The key to the capital','OCEAN FLOOR → FORGOTTEN CAPITAL','Use the submarine to recover an ancient key.',[
['Explore with the submarine','Search the northern underwater passages for a long tunnel leading to the Key to the Ancients. Approach and collect the key object.'],['Return to the capital','Travel back to the Forgotten Capital with Bugenhagen and take the western path to the device.'],['Activate the mechanism','With the Key to the Ancients, follow Bugenhagen’s instructions at the central mechanism. Watch the revealed memory.'],['Return to the Highwind','Leave the capital. After the new crisis begins, fly toward Midgar and find Diamond Weapon walking toward the city.'],['Save before contact','Land nearby and save. Touch Diamond Weapon on foot to initiate the battle.']
],[],null,'This is a good point to explore the Sunken Gelnika, obtain stronger equipment, or resolve optional character quests before the Midgar return.');
chapter(2,'Diamond Weapon','MIDGAR OUTSKIRTS','Stop the approach and prepare for the city raid.',[
['Fight Diamond Weapon','Use magic and summons while its physical immunity is active. Keep the party healthy during its countdown.'],['Survive the countdown','When its core opens, it becomes vulnerable to physical attacks. Restore HP and remove Silence after Diamond Flash.'],['Watch the aftermath','Return to the Highwind and finish the scenes. Your next destination is Midgar from the air.'],['Make a separate save','Before approaching the city, check equipment, healing items and your preferred party. The raid is a long sequence with unique treasure.'],['Begin the drop','Fly the Highwind over Midgar and follow the parachute sequence. Cait Sith will point you toward the maintenance route.']
],[],{name:'Diamond Weapon',hp:'30,000',element:'Lightning useful',tactic:'Magic and summons bypass its closed-core physical immunity. During the countdown, protect the party and be ready to cure Silence after Diamond Flash.',prep:'Lightning, summons, Echo Screens, and party healing.'});
chapter(2,'Return to Midgar','MIDGAR · FINAL RAID','A one-way raid with important detours. Bring Barret for his weapon.',[
['Explore the maintenance platforms','Follow Cait Sith through the scaffolding. Take the branching ladders for treasure before dropping into the railway tunnels.'],['Walk south for W-Item','In the underground rail tunnel, travel repeatedly toward the bottom of the screen until the far-end pickup. Then retrace your way north.'],['Resolve the Turks encounter','If you completed the Wutai rescue, you may be offered a peaceful resolution. Otherwise prepare for the group fight; stealing their rare equipment is optional.'],['Optional: revisit Shinra HQ','Take the tunnel branch leading to the building before continuing the main raid. On floor 64, inspect the locker for HP Shout. Read the lobby flyer if still needed.'],['Defeat Proud Clod','Continue the main route through the streets. Heal before the large machine battle and use strong multi-target damage.'],['Bring Barret up the stairs','Include Barret before climbing the final staircase and open the chest containing Missing Score. The chest is only present with him in the active party.'],['Confront Hojo','Save and restore the group before the top. Fight through all three forms with status protection and sustained healing. Complete the Disc 2 ending.']
],[['W-Item','Far south end of train tunnels','Take the long detour before continuing north.','important'],['HP Shout','Shinra HQ floor 64 locker','Collect during this return.','missable'],['Missing Score','Stairs before Hojo','Barret must be in the active party for the chest to appear.','missable']],{name:'Hojo · three forms',hp:'13,000 / 26,000 / 30,000',element:'Status protection',tactic:'Treat this as an endurance fight. Ribbon helps against the final form’s status-heavy combo. Heal between phases and focus the main enemy.',prep:'Ribbons or status accessories, Restore + All, revives and enough MP.'});
chapter(3,'The final preparations','WORLD · OPEN EXPLORATION','Choose your remaining goals before the last descent.',[
['Rebuild your party','Speak with your companions and prepare three characters with reliable healing, revival, damage and status protection. Equip weapons with Materia growth when training.'],['Resolve optional quests','Use Side quests for Yuffie, Vincent, Wutai, Chocobo breeding, ultimate weapons, the Gelnika, and the optional Weapons. Most are not required to finish the story.'],['Check key rewards','Review the Materia collection and outstanding chapter checklists. Disc 3 closes the Wutai Materia-theft quest, and certain earlier one-way rewards cannot be recovered.'],['Prepare a return save','Make an independent save outside the Northern Cave. Buy restorative items and consider Final Attack + Phoenix if you completed the Battle Square reward chain.'],['Head to the crater','Fly to the northern crater and land at the cave entrance when ready. The main cave can be explored and left before the final commitment.']
],[],null,'Progress here is a personal checklist, not a claim of an audited perfect-game inventory. The linked reference guides cover exhaustive steals, enemy formations and version-specific trophies.');
chapter(3,'The Northern Cave','NORTHERN CRATER','Explore every branch before the point of no return.',[
['Descend carefully','Collect the Save Crystal and follow the spiral. Open the nearby treasure chests, then continue into the branching interior.'],['Explore the split routes','At the party split, choose your route and check side ledges. Revisit accessible branches before committing at the bottom; some valuable Materia are off the direct path.'],['Collect key Materia','Look for W-Magic, Mega All, Shield and Counter along the cave routes. Mega All requires timing your interaction during the jump between ledges.'],['Train if needed','The swamp route is a strong late-game AP area. Magic Pots want an Elixir before they become vulnerable; Movers are valuable rare encounters. Save before grinding.'],['Regroup at the bottom','Speak to the party members to receive what they found. You can still backtrack from the gathering area; heal and equip everyone you intend to use.'],['Commit to the final battle','Keep an external save before entering the final descent. Past the final commitment, the ending sequence must be completed without returning to the world map.']
],[['W-Magic','Northern Cave','Explore the left-side interior routes.','materia'],['Mega All','Northern Cave ledges','Time the pickup during the automatic jump.','materia'],['Shield','Northern Cave swamp path','Inspect the off-route pickup.','materia'],['Counter','Northern Cave','Support Materia, distinct from Counter Attack.','materia']],null,'Place the one-use Save Crystal only on safe, flat ground away from ladders and transitions. Keep an earlier world-map save as a fallback.');
chapter(3,'For the planet','THE FINAL BATTLES','Finish the original journey.',[
['Defeat Jenova∙SYNTHESIS','Attack the main body and manage the arms if they disrupt you. When the countdown begins, push damage; keep protection and HP ready if Ultima goes off.'],['Fight Bizarro∙Sephiroth','The encounter can involve multiple parties depending on your playthrough. Destroy the relevant supporting parts to expose the core, then continue against the main body.'],['Prepare for Safer∙Sephiroth','Maintain Haste, defensive buffs and healing. Clear status ailments quickly, and use non-elemental attacks when elemental defenses interfere.'],['Recover from Super Nova','It deals heavy proportional damage and can inflict status ailments. Heal promptly and remove disabling conditions before resuming damage.'],['Complete the final duel','Follow the final confrontation and use Cloud’s available command. Watch the ending and post-credits sequence.'],['Close your field journal','Mark the journey complete and export your checklist if you want to preserve it. The guide does not modify your game save.']
],[],{name:'Safer∙Sephiroth',hp:'Varies with playthrough',element:'Non-elemental damage preferred',tactic:'Keep a healer free to act, renew defensive buffs, cure statuses, and use your best Limits and summons. Super Nova makes recovery more urgent than another attack.',prep:'Ribbon, strong Restore magic, revival, MP recovery, and a separate pre-finale save.'});
const Q=[
{id:'q1',title:'Recruit Yuffie',unlock:'Forests after Mythril Mine',tag:'Character',summary:'A forest encounter unlocks the first optional party member.',steps:[['Find the Mystery Ninja','Fight random battles in forests near Junon or Gongaga until the Mystery Ninja appears. Defeat her.'],['Ignore the save point','On the following field, talk directly to Yuffie. Using the apparent save point or opening the menu lets her escape.'],['Choose the five replies','In order: “Not interested” → “…petrified” → “Wait a second!” → “…That’s right” → “…Let’s hurry on.” Do not ask her name at the end.'],['Welcome her aboard','She joins as you leave. If a reply goes wrong, you can find her in another forest encounter and try again.']]},
{id:'q2',title:'Recruit Vincent',unlock:'First arrival at Nibelheim',tag:'Character',summary:'Open the mansion safe and wake its sleeping resident.',steps:[['Save before the safe','In Shinra Mansion, find the upstairs safe on the west side. Prepare for Lost Number before opening it.'],['Enter the combination','Turn RIGHT to 36, LEFT to 10, RIGHT to 59, RIGHT to 97. Confirm each number without overshooting, within the time limit.'],['Defeat Lost Number','Around half HP it specializes based on the damage type that pushes it over the threshold. Protect against its resulting physical or magical attacks and keep healing ready.'],['Collect the key and Odin','After the battle, take Odin and the key from the safe. Cosmo Memory is also awarded.'],['Talk in the basement','Unlock the coffin room before the library. Discuss Sephiroth, then ask who he is. Keep talking until he asks to sleep, then leave; Vincent catches up and joins.']]},
{id:'q3',title:'Wutai: recover your Materia',unlock:'Tiny Bronco · finish before Disc 3',tag:'Story',summary:'Visit Yuffie’s homeland with a well-stocked item bag.',steps:[['Prepare without magic','Save before arriving in the Wutai region with Yuffie recruited. Stock Hi-Potions, Phoenix Downs and offensive items; the quest temporarily removes most Materia.'],['Track Yuffie through town','Visit the Materia shop chest, inspect the folding screen in the house, and investigate the large pot outside the bar. Follow her to the house afterward.'],['Continue the chase','The lever trick leads to another escape. Follow the trail to the bell and hidden area, then cooperate with the Turks after the kidnapping.'],['Reach Da-chao','Climb the mountain paths to the confrontation. Heal before the Rapps fight.'],['Defeat Rapps','Aero3 is dangerous. Use Barret’s Mindblow to drain MP if available, spend offensive items, and heal with items. Afterward Yuffie returns the Materia.'],['Optional: climb the pagoda','Yuffie fights five solo battles for Leviathan and All Creation. Equip her carefully. Godo can teach Trine; collectors of all four Enemy Skill copies may want to postpone this fight.']]},
{id:'q4',title:'A gold Chocobo',unlock:'Highwind · best late in Disc 2',tag:'Exploration',summary:'Breed a mount that crosses every terrain type.',steps:[['Rent stables and catch parents','At the farm, rent stables. Catch Good Chocobos near Gold Saucer and Great ones near Mideel; keep a compatible opposite-sex pair. Save before breeding.'],['Train your racers','Feed Sylkis Greens for stats and race at Gold Saucer to improve breeding prospects. Obtain Carob Nuts from Vlakorados near Bone Village.'],['Breed green and blue','Breed the Good/Great pair with a Carob Nut. You need opposite-sex green and blue offspring; results involve randomness, so keep a pre-breeding save.'],['Breed a black Chocobo','Raise and race the green and blue pair, then breed them with another Carob Nut. Allow breeding cooldowns by fighting battles.'],['Catch a Wonderful Chocobo','Search the tracks near Icicle Inn. Keep the Wonderful-quality catch, train it, and make sure it is opposite sex to the black Chocobo.'],['Breed gold','Obtain a Zeio Nut by stealing from Goblins on Goblin Island in the northeast. Breed a well-trained black/Wonderful pair with it. Save first; breeding is probabilistic.'],['Visit the Materia caves','Green reaches Mime near Wutai; blue reaches Quadra Magic near Mideel; black reaches HP↔MP north of Corel; gold reaches Knights of Round on the unmarked northeastern island.']]},
{id:'q5',title:'The Sunken Gelnika',unlock:'Submarine',tag:'Dungeon',summary:'A dangerous optional wreck with outstanding equipment.',steps:[['Save before diving','Locate the crashed aircraft underwater west of Costa del Sol. Enemies are stronger than most nearby story encounters.'],['Explore the entry rooms','Collect Heaven’s Cloud and the other nearby chests. Use the save point and search the research room for Double Cut and Conformer.'],['Prepare for the Turks','Depending on story timing, Reno and Rude may be here. Attempt rare steals if desired; come prepared for a real fight.'],['Search the cargo hold','Collect Hades and the Highwind manual for Cid, plus the weapons in the hold. Check the lower sections before leaving.'],['Optional: farm Sources','With Morph and Yuffie’s Conformer, many enemies here can be turned into stat-boosting Sources. This is optional character optimization.']]},
{id:'q6',title:'Ancient Forest & Ultima Weapon',unlock:'After Diamond Weapon',tag:'Exploration',summary:'Chase the flying Weapon and open a forest full of puzzles.',steps:[['Find Ultimate Weapon','Look above the crater lake near Junon after the late-game Weapon events. Approach with the Highwind to fight it.'],['Follow its flights','After it flees, collide with it in the air until it selects another destination. Heal between rounds and repeat until it settles near Cosmo Canyon.'],['Win the last battle','Defeat it near Cosmo Canyon for Cloud’s Ultima Weapon. The resulting crater opens a walking route into Ancient Forest. A green, black or gold Chocobo can reach the forest earlier.'],['Solve the forest puzzles','Use insects and frogs as bait in pitcher plants and use hanging vines to cross gaps. Leave carnivorous plants alone unless you have bait to close them.'],['Search every tier','Check the upper canopy and cave route for Slash-All, Typhon, Apocalypse and other treasure. The reset command returns the puzzle layout if you get stuck.']]},
{id:'q7',title:'Battle Square rewards',unlock:'Gold Saucer · strongest rewards late game',tag:'Challenge',summary:'Build toward Omnislash, W-Summon and Final Attack.',steps:[['Prepare one fighter','Equip your best armor, Ribbon, healing and a strong damage option. Obtain GP through Chocobo racing or other park games to pay for entry.'],['Win consecutive rounds','Fight up to eight rounds, accepting handicaps between battles. Severe handicaps can produce more BP but may cripple your build.'],['Spend BP before leaving','BP is lost when you leave Battle Square. Check the exchange list before committing to a long run. Reward costs change with story progress.'],['Earn the late prizes','Omnislash costs 32,000 BP in the late game, W-Summon 64,000. Earlier Omnislash costs more. Use the terminal to verify current prices.'],['Unlock the special battle','Late in the game, obtain Omnislash and W-Summon and own Ultima Weapon. Speak to the attendant about the special battle and win it for Final Attack.']]},
{id:'q8',title:'Emerald & Ruby Weapon',unlock:'Submarine / late-game desert',tag:'Superboss',summary:'Optional endgame challenges. Make an independent save.',steps:[['Build reliable recovery','Raise HP and relevant Materia, equip status protection, and arrange revival on more than one character. Final Attack + Phoenix is useful insurance, but requires MP and remaining charges.'],['Remove Emerald’s timer','Morph a Ghost Ship in the Junon underwater tunnel into a Guide Book. Exchange it with the Kalm traveler for Underwater, then equip it to remove the twenty-minute limit.'],['Understand Emerald','Aire Tam Storm deals damage based on equipped Materia count: 1,111 per Materia. Fewer Materia can improve survival. Reheal after large attacks and use sustainable high damage.'],['Prepare for Ruby','Approach the desert tentacle in the buggy or on a Chocobo. Starting with two party members KO’d encourages Ruby to plant its arms; revive them once the arms are in the sand.'],['Control Ruby','Dazers or Hades can help paralyze Ruby. High defense and counterattacks make casual physical spam ineffective. Keep revival and MP recovery available.'],['Exchange the rewards','Bring the Earth Harp and Desert Rose to the Kalm traveler for the associated reward sets. These battles are not necessary to finish the story.']]},
{id:'q9',title:'Ultimate weapons & final Limits',unlock:'Mostly late Disc 2 / Disc 3',tag:'Collection',summary:'Check the party’s signature rewards before the ending.',steps:[['Cloud and Barret','Cloud: defeat Ultimate Weapon for Ultima Weapon; buy Omnislash with BP. Barret: Missing Score during the Midgar raid with him present; Catastrophe from the woman in North Corel.'],['Tifa and Red XIII','Tifa: play the Nibelheim piano with her present after Cloud’s recovery for Final Heaven; Premium Heart is in Wall Market after digging up the Sector 5 Key. Red XIII: revisit Bugenhagen late with Red XIII for Limited Moon; Cosmo Memory comes from Lost Number.'],['Yuffie and Cait Sith','Yuffie: Conformer in the Gelnika and All Creation from Godo. Cait Sith: HP Shout in Shinra HQ’s floor-64 locker during the raid; he has only two Limit levels.'],['Vincent and Cid','Vincent: visit Lucrecia’s cave with him using the submarine or suitable Chocobo, then return after at least ten battles for Death Penalty and Chaos. Cid: speak repeatedly to the Rocket Town old man late for Venus Gospel; Highwind is in the Gelnika.'],['Aeris’s early rewards','Princess Guard is in the Temple of the Ancients. Great Gospel is obtained through the Mythril exchange with the weapon seller after getting Mythril from the sleeping man east of Junon. Her goals must be completed before the Disc 1 cutoff.'],['Play Tifa’s piano','After Cloud returns on Disc 2, take Tifa to her Nibelheim bedroom. Play the notes Do–Re–Mi–Ti–La–Do–Re–Mi–So–Fa–Do–Re–Do, then end the performance. Use the note-to-button chart shown by your version; button mappings vary. The letter and Final Heaven follow the successful performance.'],['Learn the earlier Limit tiers','A final Limit manual generally requires the character to learn their earlier Limits first. Defeat enemies for the first Limit of a level and use Limits to unlock the second.']]},
{id:'q10',title:'Useful Enemy Skills',unlock:'After first Enemy Skill pickup',tag:'Materia',summary:'Equip the yellow Materia on the character who receives the skill.',steps:[['Understand learning','The equipped character must be hit by the learnable skill and survive, and you must finish the battle successfully. Each Enemy Skill Materia stores its own learned list.'],['White Wind','Manipulate Zemzelett near Junon and cast White Wind on the equipped character. It heals based on the caster’s current HP and removes many statuses.'],['Big Guard','Manipulate Beachplug on the beaches near Costa del Sol and make it target your party. This grants Barrier, MBarrier and Haste.'],['Aqualung and Trine','Harpy in the Gold Saucer desert can use Aqualung. Materia Keeper, Stilva and Godo are sources of Trine; those Trine opportunities are limited.'],['Beta','Return to Midgar Zolom with enough HP and fire protection to survive Beta. Avoid having your learner removed from battle before it casts.'],['Magic Hammer','Manipulate Razor Weed in the Wutai region to cast Magic Hammer on the learner. It drains MP and is particularly useful in drawn-out fights.']]},
{id:'q11',title:'Turtle’s Paradise & Da-chao',unlock:'Flyers throughout the journey',tag:'Collection',summary:'Read six notices and return to Wutai for the reward.',steps:[['Read the early flyers','No. 1: upstairs in the Sector 5 house. No. 2: Shinra HQ lobby, available during the initial visit or the Disc 2 raid.'],['Read the western flyers','No. 3: Ghost Hotel in Gold Saucer. No. 4: weapon shop in Cosmo Canyon. No. 5: Cosmo Canyon inn.'],['Finish in Wutai','No. 6: Yuffie’s house basement. Read the notice outside the Turtle’s Paradise bar, then talk to the proprietor after reading all six.'],['Return to the fire cave','With Leviathan Scales from the underwater reactor dock, inspect the flames in the Da-chao cave. Collect Oritsuru and Steal as well from the extinguished passages.']]}
];
const M=[
['Restore','Magic','No. 1 reactor core','Cure → Cure2 → Regen → Cure3','Link with All for party healing.'],['All','Support','Sector 7 beginner’s hall','Multi-target compatible magic','Only functions when linked to compatible Materia. Uses per battle rise with level.'],['Lightning','Magic','Cloud’s starting equipment / shops','Bolt → Bolt2 → Bolt3','Useful against many machines.'],['Fire','Magic','Shops from Midgar onward','Fire → Fire2 → Fire3','Check resistances: some enemies absorb it.'],['Ice','Magic','Starting equipment / shops','Ice → Ice2 → Ice3','A basic elemental option.'],['Earth','Magic','Kalm and later shops','Quake → Quake2 → Quake3','Often ineffective against flying enemies.'],['Poison','Magic','Shinra HQ / shops','Bio → Bio2 → Bio3','Can poison susceptible enemies.'],['Heal','Magic','Kalm and later shops','Poisona → Esuna → Resist','Status recovery and prevention.'],['Revive','Magic','Junon and later shops','Life → Life2','Keep a second revival option on another character.'],['Time','Magic','Gongaga and later shops','Haste → Slow → Stop','Haste improves action frequency.'],['Barrier','Magic','Rocket Town and later shops','Barrier → MBarrier → Reflect → Wall','MBarrier also reduces healing from magic.'],['Comet','Magic','Forgotten Capital','Comet → Comet2','Non-elemental damage.'],['Ultima','Magic','North Corel train mission','Ultima after first AP level','A new copy needs AP before it can cast.'],['Full Cure','Magic','Cosmo Canyon late-game shop back room','Full Cure after AP','Heals one target; cannot be paired with All.'],['Shield','Magic','Northern Cave','Shield after AP','Powerful temporary protection.'],['Steal','Command','Midgar sewers','Steal → Mug','Mug adds damage; stealing is chance-based.'],['Sense','Command','Sector 6 playground / shops','Sense','Displays information for susceptible enemies.'],['Enemy Skill','Command','Shinra HQ / Junon / Capital / Chocobo Sage','24 learnable enemy abilities','Four copies exist; each learns independently.'],['Manipulate','Command','Cait Sith’s starting equipment / later shops','Manip.','Control susceptible enemies to learn support Enemy Skills.'],['Morph','Command','Temple of the Ancients','Morph','A finishing hit may transform a foe into an item.'],['Double Cut','Command','Sunken Gelnika','2x-Cut → 4x-Cut','Strong repeat physical attacks.'],['Mime','Command','Cave near Wutai','Mime','Reach with a mountain-capable Chocobo.'],['W-Item','Command','Midgar raid tunnel far south','Use two items','Collect during the raid to avoid a later excavation detour.'],['W-Summon','Command','Battle Square · 64,000 BP late game','Two summon casts','Still needs equipped summons and sufficient MP.'],['W-Magic','Command','Northern Cave','Two magic casts','Pair with a caster’s existing magic.'],['Elemental','Support','Shinra HQ password reward / other locations','Elemental attack or defense','Linked weapon slots add the element; linked armor slots resist it.'],['Added Effect','Support','Cave of the Gi','Status attack or defense','Link to status-bearing Materia in a weapon or armor.'],['MP Turbo','Support','Whirlwind Maze','Stronger magic at increased MP cost','Do not leave behind during the crater visit.'],['Quadra Magic','Support','Cave near Mideel','Repeat linked spell or summon','Requires a river-capable Chocobo; not compatible with Knights of Round.'],['Final Attack','Support','Battle Square special battle','Use linked ability when KO’d','Final Attack + Phoenix needs MP and remaining uses.'],['Counter','Support','Northern Cave','Counter with linked command','Distinct from independent Counter Attack.'],['Cover','Independent','Aeris’s garden / shops','Protect allies from physical hits','Useful on a durable character.'],['Counter Attack','Independent','After Materia Keeper','Chance to retaliate physically','Does not require a linked slot.'],['HP Plus','Independent','Cosmo Canyon and later shops','Raise maximum HP','Helpful for surviving bosses without heavy grinding.'],['Long Range','Independent','Mythril Mine ledge','Full ranged physical damage','Allows a melee fighter to use the back row effectively.'],['Chocobo Lure','Independent','Chocobo Farm','Find Chocobos on tracks','Equip while walking on Chocobo footprints.'],['Underwater','Independent','Kalm traveler · Guide Book exchange','Remove Emerald’s time limit','Morph Ghost Ship in the Junon underwater tunnel.'],['Mega All','Independent','Northern Cave','Multi-target many commands','Collect by timing the interaction on a jumping ledge.'],['Choco/Mog','Summon','Chocobo Farm dance','DeathBlow!! / rare Fat-Chocobo','An early summon.'],['Shiva','Summon','Priscilla in Junon','Diamond Dust','Ice damage.'],['Ifrit','Summon','Cargo ship after Jenova∙BIRTH','Hellfire','Collect before leaving the ship.'],['Ramuh','Summon','Gold Saucer jockey room','Judgment Bolt','Collect before the prison escape race.'],['Titan','Summon','Gongaga reactor debris','Anger of the Land','Earth damage; flying enemies may be immune.'],['Odin','Summon','Nibelheim mansion safe','Steel Bladed Sword / Gunge Lance','Obtained with the Lost Number rewards.'],['Leviathan','Summon','Wutai pagoda · Godo','Tidal Wave','Yuffie must climb the pagoda.'],['Bahamut','Summon','Temple of the Ancients','Mega Flare','Non-elemental damage; collect after Red Dragon.'],['Kjata','Summon','Sleeping Forest','Tetra Disaster','Multiple elements can interact poorly with absorption.'],['Alexander','Summon','Great Glacier · Snow','Judgment','Holy damage. Touch the hot spring before visiting Snow.'],['Neo Bahamut','Summon','Whirlwind Maze','Giga Flare','Collect before the crater story cutoff.'],['Phoenix','Summon','Fort Condor after final defense','Phoenix Flame','Revives allies while dealing fire damage.'],['Hades','Summon','Sunken Gelnika cargo hold','Black Cauldron','Inflicts multiple statuses on susceptible targets.'],['Typhon','Summon','Ancient Forest','Disintegration','Called Typoon in some versions.'],['Bahamut ZERO','Summon','Blue Huge Materia at observatory','Tera Flare','Normal route needs all Huge Materia plus Bahamut and Neo Bahamut.'],['Knights of Round','Summon','Unmarked island in northeast ocean','Ultimate End','Reach its cave on a gold Chocobo.']
].map((m,i)=>({id:'m'+i,name:m[0],type:m[1],location:m[2],ability:m[3],tip:m[4]}));
const SOURCES=[['AbsoluteSteve’s complete guide','GameFAQs · supplied by you','https://gamefaqs.gamespot.com/ps/197341-final-fantasy-vii/faqs/45703'],['IGN walkthrough','Your original reference · direct access unavailable during research','https://www.ign.com/wikis/final-fantasy-vii/Walkthrough'],['Jegged walkthrough','Independent route cross-check','https://jegged.com/Games/Final-Fantasy-VII/Walkthrough/'],['RPG Site walkthrough','Progression and pickup cross-check','https://www.rpgsite.net/guide/20383-final-fantasy-vii-walkthrough-100-missable-items-materia-all-achievements-enemy-skills-step-by-step-guide'],['Huge Materia mechanics','Rocket controls and mission outcomes','https://finalfantasy.fandom.com/wiki/Huge_Materia_%28Final_Fantasy_VII%29'],['Optional characters','Recruitment sequence cross-check','https://ff7.info/secret-characters-yuffie-vincent.htm'],['Tifa’s piano reference','Final Heaven melody and controls','https://www.ffonline.com/ff7/characters/Tifa-Lockhart'],['Missable items reference','One-way pickup cross-check','https://gamefaqs.gamespot.com/ps/197341-final-fantasy-vii/faqs/27656']];
